import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';

type StatusTone = 'success' | 'warning' | 'destructive' | 'muted' | 'info' | 'outline';

/** 状态色走 token 三件套（底/描边/文字），暗色主题由 token 自动切换；口径=组件库/Badge 七形态 */
const toneClass: Record<StatusTone, string> = {
  success: 'border-success-border bg-success-soft text-success',
  warning: 'border-warning-border bg-warning-soft text-warning',
  destructive: 'border-danger-border bg-danger-soft text-danger',
  muted: 'border-border bg-background text-muted-foreground',
  info: 'border-info-border bg-info-soft text-info',
  outline: 'border-border bg-control text-foreground',
};

/** dot 变体与 default 同一套 tone 配色（软底+描边+文字）；描边形态由 Badge outline 基线提供 */
const dotMarkClass: Record<StatusTone, string> = {
  success: 'bg-success',
  warning: 'bg-warning',
  destructive: 'bg-danger',
  muted: 'bg-muted-foreground',
  info: 'bg-info',
  outline: 'bg-foreground',
};

/** 通用语义徽章：tone 决定配色，variant=dot 时为「软底+描边+前置圆点」形态（设计稿 S-05）；领域状态由下方语义包装映射成 label + tone */
export function StatusBadge({
  label,
  tone,
  variant = 'default',
}: {
  label: string;
  tone: StatusTone;
  variant?: 'default' | 'dot';
}) {
  if (variant === 'dot') {
    return (
      <Badge variant="outline" className={cn('h-5 gap-1 rounded-sm px-1.5', toneClass[tone])}>
        <span className={cn('size-1.5 shrink-0 rounded-xs', dotMarkClass[tone])} aria-hidden />
        {label}
      </Badge>
    );
  }
  return (
    <Badge variant="outline" className={toneClass[tone]}>
      {label}
    </Badge>
  );
}

/** 启用/停用语义（用户、角色、岗位、字典、文件、附件通用）；variant 可选 dot（抽屉头部等需要圆点形态处） */
export function EnabledStatusBadge({
  status,
  variant = 'default',
}: {
  status?: string | null;
  variant?: 'default' | 'dot';
}) {
  return status === 'ENABLED' ? (
    <StatusBadge label="在职" tone="success" variant={variant} />
  ) : (
    <StatusBadge label="已停用" tone="muted" variant={variant} />
  );
}

/** 可用/已废弃语义（系统配置） */
export function ConfigurationStatusBadge({ status }: { status?: string | null }) {
  return status === 'ACTIVE' ? (
    <StatusBadge label="可用" tone="success" />
  ) : (
    <StatusBadge label="已废弃" tone="muted" />
  );
}

/** UP/DOWN/DEGRADED 语义（系统运行状态） */
export function HealthStatusBadge({ status }: { status?: string | null }) {
  if (status === 'UP') {
    return <StatusBadge label="正常" tone="success" />;
  }
  if (status === 'DEGRADED') {
    return <StatusBadge label="部分降级" tone="warning" />;
  }
  return <StatusBadge label="不可用" tone="destructive" />;
}

/** 组件级 UP/DOWN 语义 */
export function ComponentStatusBadge({ status }: { status?: string | null }) {
  return status === 'UP' ? (
    <StatusBadge label="正常" tone="success" />
  ) : (
    <StatusBadge label="不可用" tone="destructive" />
  );
}

/** 审计结果语义（安全审计：成功/失败） */
export function OutcomeBadge({ outcome }: { outcome?: string | null }) {
  return outcome === 'SUCCESS' ? (
    <StatusBadge label="成功" tone="success" />
  ) : (
    <StatusBadge label="失败" tone="destructive" />
  );
}
